<?php require_once __DIR__.'/includes/admin_auth_check.php';require_once __DIR__.'/../config/db.php';$rows=[];try{$rows=db()->query('SELECT b.*,su.full_name student,tu.full_name tutor,s.name subject FROM bookings b JOIN users su ON su.id=b.student_id JOIN tutors t ON t.id=b.tutor_id JOIN users tu ON tu.id=t.user_id JOIN subjects s ON s.id=b.subject_id ORDER BY b.created_at DESC')->fetchAll();}catch(Throwable $e){}$pageTitle='All bookings';require __DIR__.'/../includes/header.php';?><main class="container py-5"><h1 class="h2">All bookings</h1><div class="table-responsive"><table class="table"><tr><th>Student</th><th>Tutor</th><th>Subject</th><th>Date</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['student'])?></td><td><?=e($r['tutor'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['booking_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></main>
